import fs from 'node:fs/promises';import path from 'node:path';import {createHash} from 'node:crypto';
const sha=x=>createHash('sha256').update(JSON.stringify(x)).digest('hex');
export async function captureInventory(roots){return Promise.all(roots.map(async root=>{let queue;try{queue=JSON.parse(await fs.readFile(path.join(root,'queue.private.json')));}catch(e){if(e.code==='ENOENT')return {queue:{items:[],total:0,rubricVersion:null},proposals:{},flags:{},unavailable:{}};throw e;}const result={queue};for(const kind of ['proposals','flags','unavailable','results','attempts']){result[kind]={};let names;try{names=await fs.readdir(path.join(root,kind));}catch(e){if(e.code!=='ENOENT')throw e;names=[];}for(const name of names.sort())if(/^[a-f0-9]{64}\.json$/.test(name))result[kind][name.slice(0,64)]=JSON.parse(await fs.readFile(path.join(root,kind,name)));}for(const [id,receipt] of Object.entries(result.results)){if(receipt.id!==id||!['proposed','needs_review'].includes(receipt.status))throw Error('Invalid durable photo result');if(receipt.status==='needs_review'){result.flags[id]={...receipt,flaggedAt:receipt.reviewedAt};delete result.proposals[id];}else if(!result.flags[id])result.proposals[id]=receipt;}delete result.results;for(const id of Object.keys(result.attempts))if(result.proposals[id]||result.flags[id])delete result.attempts[id];return result;}));}
export function pinPhotoGeneration(app,inventories){const digest=sha(inventories),gpsDigest=sha(app.matter.savedGpsContexts?.digest?{truckoom:app.matter.truckoomCurrent||null,savedAssessments:app.matter.savedGpsAssessments?.digest||null,savedContext:app.matter.savedGpsContexts.digest}:app.matter.savedGpsAssessments?.digest?{truckoom:app.matter.truckoomCurrent||null,savedAssessments:app.matter.savedGpsAssessments.digest}:app.matter.truckoomCurrent||null),previous=app.matter.automaticPhotos,baseHash=previous?.reportHash===app.matter.validatedReporting.snapshotHash?previous.baseHash:app.matter.validatedReporting.snapshotHash;if(previous?.digest===digest&&previous.gpsDigest===gpsDigest&&previous.reportHash===app.matter.validatedReporting.snapshotHash)return app;const reportHash=sha([baseHash,digest,gpsDigest]);return {...app,matter:{...app.matter,validatedReporting:{...app.matter.validatedReporting,snapshotHash:reportHash},automaticPhotos:{digest,gpsDigest,baseHash,reportHash}}};}
export function createFeedPump({pipeline,publish,acknowledge,quarantine,prepare=async app=>app}){return async({app,items})=>{const errors=[];let current=app,lastSuccessfulCapture=null;for(const item of items){let capture;try{capture=await pipeline.inspectCapture(item.folder);}catch{await quarantine?.(item.id);errors.push({id:item.id,error:'Capture verification failed; quarantined for inspection'});continue;}try{const reconciled=await pipeline.reconcileCapture(current,capture),next=await prepare(reconciled,capture);current=await publish(next,item.id,capture)||next;await acknowledge(item.id);lastSuccessfulCapture=capture.observedAt;}catch{errors.push({id:item.id,error:'Publication failed; previous report retained; retry on next poll'});}}return {app:current,errors,lastSuccessfulCapture};};}

export async function savePinnedInventory(root,inventories){const {writeImmutable}=await import('./standalone-files.mjs');await fs.mkdir(path.join(root,'queues'),{recursive:true,mode:0o700});const refs=[];for(const inventory of inventories){const {queue,...receipts}=inventory,queueDigest=sha(queue);await writeImmutable(path.join(root,'queues',queueDigest+'.json'),Buffer.from(JSON.stringify(queue)));refs.push({queueDigest,...receipts});}const digest=sha(inventories);await writeImmutable(path.join(root,digest+'.json'),Buffer.from(JSON.stringify(refs)));return digest;}
export async function loadPinnedInventory(root,digest){if(!/^[a-f0-9]{64}$/.test(digest))throw Error('Invalid inventory digest');const refs=JSON.parse(await fs.readFile(path.join(root,digest+'.json'))),inventories=[];for(const ref of refs){const {queueDigest,...receipts}=ref;if(!/^[a-f0-9]{64}$/.test(queueDigest))throw Error('Invalid queue digest');const queue=JSON.parse(await fs.readFile(path.join(root,'queues',queueDigest+'.json')));if(sha(queue)!==queueDigest)throw Error('Queue integrity failure');inventories.push({queue,...receipts});}if(sha(inventories)!==digest)throw Error('Inventory integrity failure');return inventories;}
export function isReceiptOnlyCapture(before,after){return before.queries.reporting_validated_deliveries?.rows===after.queries.reporting_validated_deliveries?.rows&&sha(before.matter.automaticPipeline?.inputHashes||{})===sha(after.matter.automaticPipeline?.inputHashes||{})&&sha((before.matter.pinnedCurrentObservations||[]).map(o=>o.id))===sha((after.matter.pinnedCurrentObservations||[]).map(o=>o.id));}
export function prioritizeCaptures(items){const ordered=[...items].sort((a,b)=>b.observedAt.localeCompare(a.observedAt)||a.id.localeCompare(b.id)),days=new Set(),first=[],rest=[];for(const item of ordered){const day=item.day||item.pointer?.day||'';if(days.has(day))rest.push(item);else{days.add(day);first.push(item);}}return [...first.sort((a,b)=>(b.day||b.pointer?.day||'').localeCompare(a.day||a.pointer?.day||'')||b.observedAt.localeCompare(a.observedAt)),...rest];}
export function combinedPhotoProgress(inventories){const groups=new Map(),legacyKeys=new Map(),rank={pending:0,unavailable:1,submitted:2,needsRecovery:3,proposed:4,needsReview:5};for(const inventory of inventories){const q=inventory.queue;for(const item of q.items){const day=item.scopeDate||item.recordKey.slice(0,10);if(item.duplicateOf||(q.completedReportDays||[]).includes(day)||q.scope&&(day<q.scope.from||day>q.scope.to))continue;const flag=inventory.flags[item.id],proposal=inventory.proposals[item.id],receipt=flag||proposal,alias=receipt?.aliasReceipt;const image=item.imageSha256||item.cachedSha256||receipt?.imageSha256||'';let key=JSON.stringify([item.datedRecordKey||item.recordKey,item.urlSha256,item.proofTimestamp??null,image]);if(alias?.legacyId&&legacyKeys.has(alias.legacyId))key=legacyKeys.get(alias.legacyId);legacyKeys.set(item.id,key);const attempt=inventory.attempts?.[item.id],status=flag?'needsReview':proposal?'proposed':attempt?attempt.status==='submitted'?'submitted':'needsRecovery':inventory.unavailable[item.id]?'unavailable':'pending';if(!groups.has(key)||rank[status]>rank[groups.get(key)])groups.set(key,status);}}const counts={total:groups.size,proposed:0,needsReview:0,needsRecovery:0,submitted:0,unavailable:0,pending:0,activeWorkers:0};for(const status of groups.values())counts[status]++;return counts;}
